/** HYB-011: route names found by REA batch 2 (2026-10-12). Names only; these routes are not wired into Tessera. */
export const HYB011_EXCLUDED_ROUTES = [
  "/api/income/wallet", "/api/income/wallet/refresh", "/api/income/methods", "/api/income/processes", "/api/income/stats", "/api/income/strategies",
  "/api/income/engine", "/api/income/execute-all", "/api/income/collect-all-profit", "/api/income/scan-airdrops", "/api/income/wallets",
  "/api/agent-secrets/all", "/api/agent-wallets", "/api/agent-wallets/transactions", "/api/agent-wallets/treasury",
  "/api/arbitrage/state", "/api/arbitrage/scan", "/api/arbitrage/start", "/api/arbitrage/risk", "/api/arbitrage/opportunities", "/api/arbitrage/conference",
  "/api/grand-council/secret-knowledge", "/api/grand-council/secret-society", "/api/secret-knowledge/all", "/api/secret-knowledge/generate-now",
  "/api/natal-chart/father", "/api/sigil/father/natal-chart", "/api/sigil/father/natal-sigil", "/api/wallets/scan",
  "/api/ad-exchange/income-tasks", "/api/ad-exchange/income-cycle",
] as const;
const PATTERNS = [/^\/api\/(income|agent-wallets|wallets|arbitrage|agent-secrets|secret-knowledge)(\/|$)/, /natal/, /\/secret-/];
export function isHyb011Excluded(route: string) {
  const r = route.split("?")[0];
  return (HYB011_EXCLUDED_ROUTES as readonly string[]).includes(r) || PATTERNS.some((p) => p.test(r));
}

/** Offline request queue + API cache. Store names: apiCache, offlineQueue only. */
export type Queued = { key: string; method: string; url: string; body?: string };
export interface Store {
  all(): Promise<Queued[]>;
  put(q: Queued): Promise<void>;
  remove(key: string): Promise<void>;
}
export const STORE_NAMES = ["apiCache", "offlineQueue"] as const;

export function memoryStore(): Store {
  const m = new Map<string, Queued>();
  return {
    async all() { return [...m.values()]; },
    async put(q) { m.set(q.key, q); },
    async remove(k) { m.delete(k); },
  };
}

export async function enqueue(store: Store, q: Queued) {
  await store.put(q); // same key overwrites: no duplicates
}

export async function replay(store: Store, send: (q: Queued) => Promise<boolean>) {
  let sent = 0;
  for (const q of await store.all()) {
    if (await send(q)) { await store.remove(q.key); sent++; }
  }
  return { sent, left: (await store.all()).length };
}

export function indexedDbStore(dbName = "TesseraOffline"): Store {
  const open = () => new Promise<IDBDatabase>((res, rej) => {
    const r = indexedDB.open(dbName, 1);
    r.onupgradeneeded = () => { for (const s of STORE_NAMES) if (!r.result.objectStoreNames.contains(s)) r.result.createObjectStore(s, { keyPath: s === "apiCache" ? "url" : "key" }); };
    r.onsuccess = () => res(r.result); r.onerror = () => rej(r.error);
  });
  const tx = async <T>(mode: IDBTransactionMode, f: (s: IDBObjectStore) => IDBRequest<T>) => {
    const db = await open();
    return new Promise<T>((res, rej) => { const q = f(db.transaction("offlineQueue", mode).objectStore("offlineQueue")); q.onsuccess = () => res(q.result); q.onerror = () => rej(q.error); });
  };
  return {
    all: () => tx("readonly", (s) => s.getAll() as IDBRequest<Queued[]>),
    put: async (q) => { await tx("readwrite", (s) => s.put(q)); },
    remove: async (k) => { await tx("readwrite", (s) => s.delete(k)); },
  };
}

/**
 * O11 — secure mesh layer.
 * Ed25519 + AES-256-GCM/HKDF (no colonial/sacred keys). Shepherd-style audit.
 * Group key + signatures (honest: no X25519 sealed box without a new dep).
 * Default MemoryTransport; no WAN. See SECURITY-PROTOCOLS-INVENTORY.md.
 */
import {
  createHash, createCipheriv, createDecipheriv, randomBytes, hkdfSync,
  generateKeyPairSync, createPrivateKey, createPublicKey, sign, verify,
} from "node:crypto";

export type Audit = { at: number; action: string; outcome: "allowed" | "refused"; reason?: string; topic?: string; cid?: string };
export type Envelope = { v: 1; alg: "aes-256-gcm"; cid: string; topic: string; from: string; iv: string; tag: string; ct: string; sig: string };
export type Peer = { nodeId: string; publicKeyPem: string };
export interface Transport {
  readonly name: string;
  publish(topic: string, frame: Uint8Array): Promise<void>;
  subscribe(topic: string, handler: (frame: Uint8Array, meta: { fromTransport: string }) => void): () => void;
}

export class MemoryTransport implements Transport {
  readonly name: string;
  private static buses = new Map<string, Set<(f: Uint8Array, m: { fromTransport: string }) => void>>();
  private channel: string;
  constructor(channel = "default") { this.channel = channel; this.name = `memory:${channel}`; }
  private bus(topic: string) {
    const k = this.channel + "|" + topic;
    if (!MemoryTransport.buses.has(k)) MemoryTransport.buses.set(k, new Set());
    return MemoryTransport.buses.get(k)!;
  }
  async publish(topic: string, frame: Uint8Array) { for (const h of [...this.bus(topic)]) h(frame, { fromTransport: this.name }); }
  subscribe(topic: string, handler: (frame: Uint8Array, meta: { fromTransport: string }) => void) {
    this.bus(topic).add(handler); return () => this.bus(topic).delete(handler);
  }
  static reset() { MemoryTransport.buses.clear(); }
}

export function contentId(plaintext: string | Uint8Array) { return createHash("sha256").update(plaintext).digest("hex"); }
export function topicId(name: string) { return createHash("sha256").update("tessera-topic:" + name).digest("hex").slice(0, 32); }
export function makeGroupKey() { return randomBytes(32); }
function deriveMsgKey(groupKey: Buffer, cid: string) {
  return Buffer.from(hkdfSync("sha256", groupKey, Buffer.from(cid, "hex"), Buffer.from("tessera-secure-mesh-v1"), 32));
}

export class SecureMesh {
  readonly nodeId: string;
  readonly publicKeyPem: string;
  private priv: string;
  private groupKey: Buffer;
  private peers = new Map<string, Peer>();
  private transports: Transport[];
  private unsubs: Array<() => void> = [];
  audit: Audit[] = [];
  quarantine: Envelope[] = [];
  inbox: Array<{ topic: string; cid: string; text: string; from: string }> = [];

  constructor(groupKey: Buffer, transports: Transport[] = [new MemoryTransport()]) {
    const { publicKey, privateKey } = generateKeyPairSync("ed25519");
    this.publicKeyPem = publicKey.export({ type: "spki", format: "pem" }).toString();
    this.priv = privateKey.export({ type: "pkcs8", format: "pem" }).toString();
    this.nodeId = createHash("sha256").update(this.publicKeyPem).digest("hex").slice(0, 16);
    this.groupKey = groupKey;
    this.transports = transports;
  }
  asPeer(): Peer { return { nodeId: this.nodeId, publicKeyPem: this.publicKeyPem }; }
  addPeer(p: Peer) {
    if (createHash("sha256").update(p.publicKeyPem).digest("hex").slice(0, 16) !== p.nodeId) {
      this.log("addPeer", "refused", "nodeId does not match public key"); return false;
    }
    this.peers.set(p.nodeId, p); this.log("addPeer", "allowed"); return true;
  }
  private log(action: string, outcome: "allowed" | "refused", reason?: string, extra?: Partial<Audit>) {
    this.audit.push({ at: Date.now(), action, outcome, reason, ...extra });
  }
  encrypt(topicName: string, plaintext: string): Envelope {
    const cid = contentId(plaintext); const topic = topicId(topicName);
    const key = deriveMsgKey(this.groupKey, cid); const iv = randomBytes(12);
    const c = createCipheriv("aes-256-gcm", key, iv);
    const ct = Buffer.concat([c.update(plaintext, "utf8"), c.final()]); const tag = c.getAuthTag();
    const body = [cid, topic, this.nodeId, iv.toString("base64"), tag.toString("base64"), ct.toString("base64")].join("|");

/**
 * O10 — node per install (opt-in).
 * - Mesh is OFF until the install owner turns it on (visible toggle in settings). Nothing is sent while off.
 * - Node identity: one ed25519 keypair made on first run, stored only in the local data dir (0600). The private key never leaves the device and is never sent.
 * - Agents may join/decline/leave with a logged reason, but only while the owner toggle is on.
 * - Discovery: LAN multicast announce (mDNS-style group 224.0.0.251, own JSON payload, not full DNS-SD).
 * - Sharing: read-only HTTP of cached Gitbook/GitMesh pages; pages are signed by the node key and verified on fetch.
 * - No self-copying, no installing anything on peers, no background traffic while off. No wallet or other keys.
 */
import { createHash, generateKeyPairSync, createPrivateKey, createPublicKey, sign, verify } from "node:crypto";
import { mkdirSync, readFileSync, writeFileSync, existsSync, appendFileSync } from "node:fs";
import { join } from "node:path";
import dgram from "node:dgram";
import http from "node:http";

export type Identity = { nodeId: string; publicKeyPem: string };
export type Page = { path: string; text: string };
export type AgentChoice = { at: string; agent: string; action: "join" | "decline" | "leave"; reason: string; ok: boolean; note?: string };

export function loadOrCreateIdentity(dataDir: string): Identity & { privateKeyPem: string } {
  mkdirSync(dataDir, { recursive: true });
  const file = join(dataDir, "node-identity.json");
  if (existsSync(file)) return JSON.parse(readFileSync(file, "utf8"));
  const { publicKey, privateKey } = generateKeyPairSync("ed25519");
  const publicKeyPem = publicKey.export({ type: "spki", format: "pem" }).toString();
  const privateKeyPem = privateKey.export({ type: "pkcs8", format: "pem" }).toString();
  const nodeId = createHash("sha256").update(publicKeyPem).digest("hex").slice(0, 16);
  const id = { nodeId, publicKeyPem, privateKeyPem };
  writeFileSync(file, JSON.stringify(id), { mode: 0o600 });
  return id;
}

export type NodeOptions = { dataDir: string; group?: string; discoveryPort?: number; httpHost?: string };

export class MeshNode {
  readonly id: Identity;
  private priv: string;
  private settingsFile: string;
  private logFile: string;
  pages = new Map<string, Page>();
  peers = new Map<string, { nodeId: string; url: string; publicKeyPem: string }>();
  agents = new Set<string>();
  private sock?: dgram.Socket;
  private server?: http.Server;
  url = "";

  private opt: NodeOptions;

  constructor(opt: NodeOptions) {
    this.opt = opt;
    const full = loadOrCreateIdentity(opt.dataDir);
    this.priv = full.privateKeyPem;
    this.id = { nodeId: full.nodeId, publicKeyPem: full.publicKeyPem };
    this.settingsFile = join(opt.dataDir, "mesh-settings.json");
    this.logFile = join(opt.dataDir, "agent-mesh-choices.jsonl");
  }

  /** Owner toggle. Default false. */
  get enabled(): boolean {
    return existsSync(this.settingsFile) ? JSON.parse(readFileSync(this.settingsFile, "utf8")).meshEnabled === true : false;
  }
  setEnabled(on: boolean) {
    writeFileSync(this.settingsFile, JSON.stringify({ meshEnabled: on }));
    if (!on) void this.stop();
  }

  private record(c: Omit<AgentChoice, "at">): AgentChoice {
    const row = { at: new Date().toISOString(), ...c };
    appendFileSync(this.logFile, JSON.stringify(row) + "\n");
    return row;
  }
  agentJoin(agent: string, reason: string) {
    if (!this.enabled) return this.record({ agent, action: "join", reason, ok: false, note: "owner mesh toggle is off" });
    this.agents.add(agent);
    return this.record({ agent, action: "join", reason, ok: true });
  }
  agentDecline(agent: string, reason: string) {
    this.agents.delete(agent);
    return this.record({ agent, action: "decline", reason, ok: true });
  }

/** Offline search index built from Gitbook/GitMesh pages already on disk. No network. */
export type Page = { path: string; text: string };
export type Index = { version: 1; pages: Page[] };

const words = (s: string) => s.toLowerCase().split(/[^a-z0-9]+/).filter((w) => w.length > 2);

export function buildIndex(pages: Page[], maxChars = 2048): Index {
  return { version: 1, pages: pages.map((p) => ({ path: p.path, text: p.text.slice(0, maxChars) })) };
}

export function searchIndex(index: Index, query: string, limit = 5) {
  const q = words(query);
  if (!q.length) return { live: false as const, hits: [] as string[] };
  const scored = index.pages
    .map((p) => {
      const t = p.text.toLowerCase() + " " + p.path.toLowerCase();
      const matched = q.filter((w) => t.includes(w)).length;
      return { path: p.path, matched };
    })
    .filter((s) => s.matched === q.length)
    .sort((a, b) => a.path.localeCompare(b.path));
  return { live: false as const, hits: scored.slice(0, limit).map((s) => s.path) };
}

// Tessera app-shell service worker. Same-origin GET only; /api/* and non-GET are never cached.
const CACHE = "tessera-shell-v1";
const SHELL = ["/", "/index.html"];
self.addEventListener("install", (e) => e.waitUntil(caches.open(CACHE).then((c) => c.addAll(SHELL))));
self.addEventListener("activate", (e) => e.waitUntil(caches.keys().then((ks) => Promise.all(ks.filter((k) => k !== CACHE).map((k) => caches.delete(k))))));
self.addEventListener("fetch", (e) => {
  const r = e.request; const u = new URL(r.url);
  if (r.method !== "GET" || u.origin !== location.origin || u.pathname.startsWith("/api/")) return;
  const shell = SHELL.includes(u.pathname) || /\.(js|css|svg|png|woff2?)$/.test(u.pathname);
  if (shell) { e.respondWith(caches.match(r).then((hit) => hit || fetch(r).then((res) => { const c = res.clone(); caches.open(CACHE).then((x) => x.put(r, c)); return res; }))); return; }
  e.respondWith(fetch(r).then((res) => { const c = res.clone(); caches.open(CACHE).then((x) => x.put(r, c)); return res; }).catch(() => caches.match(r).then((hit) => hit || caches.match("/index.html"))));
});

/** Optional read-only Kiwix lookup. OFF by default; only a local kiwix-serve URL the owner sets. */
export type KiwixConfig = { enabled: boolean; baseUrl: string };
export const DEFAULT_KIWIX: KiwixConfig = { enabled: false, baseUrl: "" };
const LOCAL = /^https?:\/\/(localhost|127\.0\.0\.1|10\.|192\.168\.|172\.(1[6-9]|2\d|3[01])\.)/;

export async function kiwixSearch(cfg: KiwixConfig, query: string, fetchFn: typeof fetch = fetch) {
  if (!cfg.enabled) return { used: false as const, reason: "kiwix is off" };
  if (!LOCAL.test(cfg.baseUrl)) return { used: false as const, reason: "kiwix url must be local" };
  const url = `${cfg.baseUrl.replace(/\/$/, "")}/search?pattern=${encodeURIComponent(query)}&format=xml&pageLength=5`;
  const res = await fetchFn(url);
  if (!res.ok) return { used: false as const, reason: `kiwix ${res.status}` };
  const xml = await res.text();
  const titles = [...xml.matchAll(/<title>([^<]*)<\/title>/g)].map((m) => m[1]).filter((t) => !/^Search/i.test(t));
  return { used: true as const, titles };
}
export const isOfflineWikiQuery = (q: string) => /\b(offline wiki|kiwix|wikipedia offline)\b/i.test(q);

#!/usr/bin/env node
// Sneakernet: carry a git repo on USB as one file.
//   node mesh-bundle.mjs create <repo-dir> <out.bundle>
//   node mesh-bundle.mjs verify <file.bundle>
//   node mesh-bundle.mjs open   <file.bundle> <new-dir>
import { execFileSync } from "node:child_process";
const [cmd, a, b] = process.argv.slice(2);
const git = (args, cwd) => execFileSync("git", args, { cwd, stdio: ["ignore", "pipe", "pipe"] }).toString();
if (cmd === "create") { git(["bundle", "create", b, "--all"], a); console.log(`wrote ${b}`); }
else if (cmd === "verify") { const heads = git(["bundle", "list-heads", a]); if (!heads.trim()) { console.error("empty bundle"); process.exit(1); } console.log("bundle ok"); }
else if (cmd === "open") { git(["clone", a, b]); console.log(`opened into ${b}`); }
else { console.error("usage: mesh-bundle.mjs create|verify|open ..."); process.exit(2); }

/** LAN mode for p2p.ts: no public STUN/TURN, host candidates only, local signaling URL. */
export function lanIceServers(): RTCIceServer[] { return []; }
export function isLocalSignal(url: string) {
  return /^(\/|https?:\/\/(localhost|127\.0\.0\.1|10\.|192\.168\.|172\.(1[6-9]|2\d|3[01])\.))/.test(url);
}
export function lanRoomConfig(signalUrl = "/api/rtc") {
  if (!isLocalSignal(signalUrl)) throw new Error("LAN mode needs a local signaling url");
  return { iceServers: lanIceServers(), signalUrl, iceTransportPolicy: "all" as const };
}

import assert from "node:assert/strict";
import test from "node:test";
import { buildIndex, searchIndex } from "./offline-index.ts";

test("index of 60 pages finds a real page without the live web", () => {
  const pages = Array.from({ length: 60 }, (_, i) => ({ path: `mesh/page-${i}.md`, text: `page ${i} filler words` }));
  pages.push({ path: "mesh/offline-internet.md", text: "Offline internet: kiwix, sneakernet bundle, LAN p2p" });
  const idx = buildIndex(pages);
  assert.ok(idx.pages.length >= 50);
  const r = searchIndex(idx, "sneakernet bundle");
  assert.deepEqual(r.hits, ["mesh/offline-internet.md"]);
  assert.equal(r.live, false);
  assert.deepEqual(searchIndex(idx, "nothing-here-xyz").hits, []);
});

test("long pages are trimmed", () => {
  const idx = buildIndex([{ path: "a.md", text: "x".repeat(5000) }], 100);
  assert.equal(idx.pages[0].text.length, 100);
});

#!/usr/bin/env node
// Usage: node gen-offline-index.mjs <gitbook-clone-dir> <out.json>
// Reads .md files on disk (skips archive/, 1T, vault). No network.
import { readdirSync, readFileSync, writeFileSync, statSync } from "node:fs";
import { join, relative } from "node:path";
const [root, out] = process.argv.slice(2);
if (!root || !out) { console.error("usage: gen-offline-index.mjs <dir> <out.json>"); process.exit(2); }
const skip = /(^|\/)(archive|\.git|node_modules|1T)(\/|$)|vault/i;
const pages = [];
(function walk(d) {
  for (const n of readdirSync(d)) {
    const p = join(d, n); const r = relative(root, p);
    if (skip.test(r)) continue;
    const s = statSync(p);
    if (s.isDirectory()) walk(p); else if (n.endsWith(".md")) pages.push({ path: r, text: readFileSync(p, "utf8").slice(0, 2048) });
  }
})(root);
writeFileSync(out, JSON.stringify({ version: 1, pages }));
console.log(`indexed ${pages.length} pages`);

import assert from "node:assert/strict";
import test from "node:test";
import { enqueue, memoryStore, replay, STORE_NAMES } from "./queue.ts";

test("queued POST replays once on reconnect, no duplicates", async () => {
  const s = memoryStore();
  await enqueue(s, { key: "a", method: "POST", url: "/api/x", body: "1" });
