/**
 * Small checker for the studio websocket schemas.
 * Covers the subset those schemas use: object, string, enum, required, minLength.
 */
import { readFileSync } from "node:fs";
import { dirname, join } from "node:path";
import { fileURLToPath } from "node:url";

export function validate(schema, value, path = "$") {
  const errors = [];
  if (schema.type === "object") {
    if (value === null || typeof value !== "object" || Array.isArray(value)) {
      errors.push(`${path} should be an object`);
      return errors;
    }
    for (const key of schema.required ?? []) {
      if (!Object.hasOwn(value, key)) errors.push(`${path}.${key} is required`);
    }
    const known = schema.properties ?? {};
    if (schema.additionalProperties === false) {
      for (const key of Object.keys(value)) {
        if (!Object.hasOwn(known, key)) errors.push(`${path}.${key} is not allowed`);
      }
    }
    for (const [key, child] of Object.entries(known)) {
      if (Object.hasOwn(value, key)) errors.push(...validate(child, value[key], `${path}.${key}`));
    }
    return errors;
  }
  if (schema.type === "string") {
    if (typeof value !== "string") errors.push(`${path} should be a string`);
    else {
      if (schema.minLength && value.length < schema.minLength) errors.push(`${path} is too short`);
      if (schema.enum && !schema.enum.includes(value)) errors.push(`${path} is not an allowed value`);
    }
  }
  return errors;
}

export function protocolDir() {
  return join(dirname(fileURLToPath(import.meta.url)), "../../../../docs/v2/protocol");
}

export function loadProtocol(dir = protocolDir()) {
  const schema = JSON.parse(readFileSync(join(dir, "messages.schema.json"), "utf8"));
  const examples = JSON.parse(readFileSync(join(dir, "examples.json"), "utf8"));
  return { schema, examples };
}

export function checkExamples(dir = protocolDir()) {
  const { schema, examples } = loadProtocol(dir);
  const errors = [];
  for (const [index, message] of examples.entries()) {
    const shape = schema.messages?.[message.type];
    if (!shape) {
      errors.push(`example ${index} has unknown type ${message.type}`);
      continue;
    }
    for (const error of validate(shape, message)) errors.push(`example ${index}: ${error}`);
  }

/**
 * Foreman task graph and decision queue.
 * Clean-room of the AgentCraft pattern: dependencies gate start,
 * an open decision blocks the worker, a decision resumes it.
 * No model calls.
 */

export function createForeman() {
  let nextDecision = 1;
  const tasks = new Map();
  const decisions = new Map();

  function task(id) {
    const found = tasks.get(id);
    if (!found) throw new Error(`missing task ${id}`);
    return found;
  }

  function depsDone(item) {
    return item.dependsOn.every((dep) => tasks.get(dep)?.status === "done");
  }

  function openDecisionFor(taskId) {
    return [...decisions.values()].find((item) => item.taskId === taskId && item.status === "open") ?? null;
  }

  return {
    addTask({ id, title, dependsOn = [] }) {
      if (tasks.has(id)) throw new Error(`duplicate task ${id}`);
      for (const dep of dependsOn) task(dep);
      const item = { id, title, dependsOn: [...dependsOn], status: "pending" };
      tasks.set(id, item);
      return item;
    },
    requestDecision({ taskId, question }) {
      task(taskId).status = "blocked";
      const decision = {
        id: `d${nextDecision++}`,
        taskId,
        question,
        status: "open",
        answer: null,
      };
      decisions.set(decision.id, decision);
      return decision;
    },
    decide(decisionId, answer) {
      const decision = decisions.get(decisionId);
      if (!decision || decision.status !== "open") throw new Error("no open decision");
      decision.status = "closed";
      decision.answer = answer;
      const item = task(decision.taskId);
      if (!openDecisionFor(item.id) && depsDone(item)) item.status = "pending";
      return decision;
    },
    start(id) {
      const item = task(id);
      if (!depsDone(item)) throw new Error("dependencies open");
      if (item.status === "blocked" || openDecisionFor(id)) throw new Error("decision blocks worker");
      if (item.status === "done" || item.status === "running") throw new Error(`cannot start ${item.status}`);
      item.status = "running";
      return item;
    },
    complete(id) {
      const item = task(id);
      if (item.status !== "running") throw new Error("not running");
      item.status = "done";
      return item;
    },
    snapshot() {
      return {
        tasks: [...tasks.values()].map((item) => ({ ...item, dependsOn: [...item.dependsOn] })),
        decisions: [...decisions.values()].map((item) => ({ ...item })),
      };
    },
  };
}

  }
  return errors;
}

export function checkMessage(message, dir = protocolDir()) {
  const { schema } = loadProtocol(dir);
  const shape = schema.messages?.[message?.type];
  if (!shape) return [`unknown type ${message?.type}`];
  return validate(shape, message);
}

