/**
 * Foreman task graph and decision queue.
 * Clean-room of the AgentCraft pattern: dependencies gate start,
 * an open decision blocks the worker, a decision resumes it.
 * No model calls.
 */

export function createForeman() {
  let nextDecision = 1;
  const tasks = new Map();
  const decisions = new Map();

  function task(id) {
    const found = tasks.get(id);
    if (!found) throw new Error(`missing task ${id}`);
    return found;
  }

  function depsDone(item) {
    return item.dependsOn.every((dep) => tasks.get(dep)?.status === "done");
  }

  function openDecisionFor(taskId) {
    return [...decisions.values()].find((item) => item.taskId === taskId && item.status === "open") ?? null;
  }

  return {
    addTask({ id, title, dependsOn = [] }) {
      if (tasks.has(id)) throw new Error(`duplicate task ${id}`);
      for (const dep of dependsOn) task(dep);
      const item = { id, title, dependsOn: [...dependsOn], status: "pending" };
      tasks.set(id, item);
      return item;
    },
    requestDecision({ taskId, question }) {
      task(taskId).status = "blocked";
      const decision = {
        id: `d${nextDecision++}`,
        taskId,
        question,
        status: "open",
        answer: null,
      };
      decisions.set(decision.id, decision);
      return decision;
    },
    decide(decisionId, answer) {
      const decision = decisions.get(decisionId);
      if (!decision || decision.status !== "open") throw new Error("no open decision");
      decision.status = "closed";
      decision.answer = answer;
      const item = task(decision.taskId);
      if (!openDecisionFor(item.id) && depsDone(item)) item.status = "pending";
      return decision;
    },
    start(id) {
      const item = task(id);
      if (!depsDone(item)) throw new Error("dependencies open");
      if (item.status === "blocked" || openDecisionFor(id)) throw new Error("decision blocks worker");
      if (item.status === "done" || item.status === "running") throw new Error(`cannot start ${item.status}`);
      item.status = "running";
      return item;
    },
    complete(id) {
      const item = task(id);
      if (item.status !== "running") throw new Error("not running");
      item.status = "done";
      return item;
    },
    snapshot() {
      return {
        tasks: [...tasks.values()].map((item) => ({ ...item, dependsOn: [...item.dependsOn] })),
        decisions: [...decisions.values()].map((item) => ({ ...item })),
      };
    },
  };
}

/**
 * Worker tool events land on a monitor the API can read.
 */
import { createServer } from "node:http";
import { checkMessage } from "./protocol.mjs";

export function createMonitor() {
  const events = [];
  return {
    emit(event) {
      const row = {
        type: "worker.event",
        taskId: event.taskId,
        name: event.name,
        detail: event.detail ?? "",
      };
      const errors = checkMessage(row);
      if (errors.length) throw new Error(errors.join("; "));
      events.push(row);
      return row;
    },
    list() {
      return events.map((event) => ({ ...event }));
    },
  };
}

export function fakeWorker(monitor, taskId = "t1") {
  monitor.emit({ taskId, name: "tool.read", detail: "docs/v2/README.md" });
  monitor.emit({ taskId, name: "tool.write", detail: "studio note" });
  return monitor.list();
}

export function listenMonitor(monitor = createMonitor()) {
  const server = createServer((req, res) => {
    if (req.method === "GET" && req.url === "/events") {
      res.writeHead(200, { "content-type": "application/json" });
      res.end(JSON.stringify({ events: monitor.list() }));
      return;
    }
    res.writeHead(404);
    res.end();
  });
  return new Promise((resolve) => {
    server.listen(0, "127.0.0.1", () => {
      const { port } = server.address();
      resolve({ server, url: `http://127.0.0.1:${port}` });
    });
  });
}

/**
 * Studio messages in the V2-013 websocket shapes.
 * worker.event rows come from the V2-017 monitor.
 */
import { createHash } from "node:crypto";
import { checkMessage } from "./protocol.mjs";

export function liveMessages(state, events = []) {
  const messages = [];
  for (const task of state.tasks ?? []) {
    messages.push({
      type: "task.upsert",
      id: task.id,
      title: task.title,
      status: task.status,
    });
  }
  for (const event of events) {
    messages.push({
      type: "worker.event",
      taskId: event.taskId,
      name: event.name,
      detail: event.detail ?? "",
    });
  }
  for (const message of messages) {
    const errors = checkMessage(message);
    if (errors.length) throw new Error(errors.join("; "));
  }
  return messages;
}

const WS_GUID = "258EAFA5-E914-47DA-95CA-C5AB0DC85B11";

export function acceptWebSocket(req, socket) {
  const key = req.headers["sec-websocket-key"];
  if (!key) {
    socket.destroy();
    return false;
  }
  const accept = createHash("sha1").update(String(key) + WS_GUID).digest("base64");
  socket.write(
    `HTTP/1.1 101 Switching Protocols\r\nUpgrade: websocket\r\nConnection: Upgrade\r\nSec-WebSocket-Accept: ${accept}\r\n\r\n`,
  );
  return true;
}

export function textFrame(text) {
  const payload = Buffer.from(text);
  if (payload.length < 126) return Buffer.concat([Buffer.from([0x81, payload.length]), payload]);
  const header = Buffer.alloc(4);
  header[0] = 0x81;
  header[1] = 126;
  header.writeUInt16BE(payload.length, 2);
  return Buffer.concat([header, payload]);
}

