        if (steps >= TICK_STEP_CAP) break;
        state.seenEvents += 1;
        const owner = state.agents.worker;
        if (!owner) continue;
        remember(state, "worker", `${event.name} ${event.detail || event.taskId || ""}`.trim());
        if (event.name === "tool.write") {
          addProject(owner, event.detail || event.taskId);

