/**
 * Open the 3D studio in a browser.
 *   pnpm --filter @workspace/v2 studio
 */
import { realpathSync } from "node:fs";
import { dirname, join } from "node:path";
import { fileURLToPath } from "node:url";
import { createCivic } from "./civic.mjs";
import { loadCivic } from "./civic-store.mjs";
import { createStudio, listenStudio } from "./wall.mjs";
import { createMonitor, fakeWorker } from "./worker-stream.mjs";

export async function openDemoStudio({ port = 0, civicPath = null } = {}) {
  const studio = createStudio();
  const monitor = createMonitor();
  studio.postGoal("Lay out the offices");
  studio.runNext();
  studio.finishRunning();
  studio.runNext();
  fakeWorker(monitor, "g1-work");
  const saved = civicPath ? loadCivic(civicPath) : null;
  const civic = createCivic(saved);
  if (!saved) {
    const proposal = civic.propose("worker", {
      title: "Raise a reading room",
      kind: "upgrade",
      change: { agentId: "worker", levels: 1 },
    });
    civic.vote("worker", proposal.id, "yes");
  }
  civic.tick({ tasks: studio.state().tasks, events: monitor.list() });
  return listenStudio(studio, { monitor, port, civic, civicPath });
}

const launchedDirectly = process.argv[1] && realpathSync(process.argv[1]) === realpathSync(fileURLToPath(import.meta.url));
if (launchedDirectly) {
  const civicPath = join(dirname(fileURLToPath(import.meta.url)), "../../data/civic-world.json");
  const started = await openDemoStudio({ port: Number(process.env.PORT || 4173), civicPath });
  console.log(`Tessera 3D studio: ${started.url}`);
  console.log(`2D wall: ${started.url}?view=2d`);
}

/**
 * HYB-011 route and file denylist.
 * Refuses wallet, payment, vault, and 1T paths on the v2 surface.
 * Clean-room gate. It does not delete existing files or rewrite history.
 */

const REFUSED_SEGMENT =
  /^(?:1t|vault|wallets?|payments?|checkout|stripe|mining|nft|defi|mev|hashcat|captcha|antidetect)$/i;

const EMBEDDED_REFUSED = /(?:vault|wallet|payment|1t)/i;

function decodePart(value) {
  try {
    return decodeURIComponent(value);
  } catch {
    return value;
  }
}

function segmentsOf(value) {
  return decodePart(String(value ?? ""))
    .replace(/\\/g, "/")
    .split(/[?#]/, 1)[0]
    .split("/")
    .filter((part) => part.length > 0 && part !== "." && part !== "..");
}

function segmentRefused(segment) {
  if (REFUSED_SEGMENT.test(segment)) return segment.toLowerCase();
  if (/(?:^|[^a-z0-9])1t(?:[^a-z0-9]|$)/i.test(segment)) return "1t";
  if (/vault/i.test(segment)) return "vault";
  if (/wallets?/i.test(segment)) return "wallet";
  if (/payments?/i.test(segment)) return "payment";
  return null;
}

export function reviewPath(value) {
  const segments = segmentsOf(value);
  for (const segment of segments) {
    const hit = segmentRefused(segment);
    if (hit) {
      return { allowed: false, status: 403, reason: "hyb-011-denied", match: hit };
    }
  }
  const query = String(value ?? "").includes("?")
    ? decodePart(String(value).slice(String(value).indexOf("?") + 1))
    : "";
  if (query) {
    for (const piece of query.split(/[&/=]/)) {
      const hit = segmentRefused(piece);
      if (hit) {
        return { allowed: false, status: 403, reason: "hyb-011-denied", match: hit };
      }
    }
  }
  return { allowed: true, status: 200, reason: "ok", match: null };
}

export function reviewRequest({ url = "/", method = "GET" } = {}) {
  const decision = reviewPath(url);
  return { ...decision, method: String(method || "GET").toUpperCase() };
}

export function reviewFile(filePath) {
  const decision = reviewPath(filePath);
  if (!decision.allowed) return decision;
  const base = segmentsOf(filePath).at(-1) ?? "";
  if (EMBEDDED_REFUSED.test(base) && segmentRefused(base)) {
    return { allowed: false, status: 403, reason: "hyb-011-denied", match: segmentRefused(base) };
  }
  return decision;
}

export function createGateServer() {
  return async function gate(request) {
    const decision = reviewRequest({ url: request.url, method: request.method });
    const body = decision.allowed
      ? { ok: true }
      : { refused: true, reason: decision.reason, match: decision.match };
    return new Response(JSON.stringify(body), {
      status: decision.status,
      headers: { "content-type": "application/json" },
    });
  };
}

/**
 * Offline file mesh. Pages already on disk. A query never opens the live web.
 */
import { readdirSync, readFileSync, statSync } from "node:fs";
import { dirname, join, relative, resolve } from "node:path";
import { fileURLToPath } from "node:url";
import { reviewFile } from "../hyb011-denylist.mjs";
import { buildIndex, searchIndex } from "../../../../preview/src/lib/tessera/offline-index.ts";

const SKIP_DIR = new Set(["node_modules", ".git"]);

export function gitbookRoot() {
  return resolve(dirname(fileURLToPath(import.meta.url)), "../../../../archive/from-gitbook");
}

export function loadGitbookPages(root = gitbookRoot()) {
  const pages = [];
  function walk(dir) {
    for (const name of readdirSync(dir)) {
      if (SKIP_DIR.has(name)) continue;
      const abs = join(dir, name);
      const rel = relative(root, abs);
      if (!reviewFile(rel).allowed) continue;
      const info = statSync(abs);
      if (info.isDirectory()) walk(abs);
      else if (name.endsWith(".md")) {
        pages.push({ path: rel, text: readFileSync(abs, "utf8").slice(0, 2048) });
      }
    }
  }
  walk(root);
  return pages;
}

export function queryFileMesh(query, root = gitbookRoot()) {
  const pages = loadGitbookPages(root);
  const index = buildIndex(pages);
  const found = searchIndex(index, query, 20);
  return { ...found, count: index.pages.length };
}

import assert from "node:assert/strict";
import { createServer } from "node:http";
import test from "node:test";
import { createGateServer, reviewFile, reviewRequest } from "../src/hyb011-denylist.mjs";

const REFUSED = [
  "/wallet",
  "/api/wallet/balance",
  "/payments/checkout",
  "/payment/stripe",
  "/vault/secrets",
  "/data/vault/notes.md",
  "/1T/parts/000",
  "/repos/1t/readme",
  "/files?path=vault/hidden",
  "/open?repo=1T",
];

test("fixture requests to wallet, payment, vault, and 1T paths are refused", async () => {
  const gate = createGateServer();
  for (const url of REFUSED) {
    const decision = reviewRequest({ url, method: "GET" });
    assert.equal(decision.allowed, false, url);
    assert.equal(decision.status, 403, url);
    const response = await gate(new Request(`http://v2.local${url}`));
    assert.equal(response.status, 403, url);
    const body = await response.json();
    assert.equal(body.refused, true, url);
    assert.equal(body.reason, "hyb-011-denied");
  }
});

test("ordinary studio and mesh routes stay open", async () => {
  const gate = createGateServer();
  for (const url of ["/studio/tasks", "/mesh/index", "/health", "/knowledge/graph"]) {
    const decision = reviewRequest({ url });
    assert.equal(decision.allowed, true, url);
    const response = await gate(new Request(`http://v2.local${url}`));
    assert.equal(response.status, 200, url);
  }
});

test("file admission refuses vault, wallet, payment, and 1T paths", () => {
  for (const filePath of [
    "1T/secret.md",
    "archive/vault/notes.txt",
    "routes/wallet.ts",
    "routes/payments/checkout.ts",
    "src/sacred-knowledge-vault.ts",
  ]) {
    assert.equal(reviewFile(filePath).allowed, false, filePath);
  }
  assert.equal(reviewFile("docs/v2/BUILD-LOG.md").allowed, true);
  assert.equal(reviewFile("artifacts/v2/src/hyb011-denylist.mjs").allowed, true);
});

test("a loopback fixture server refuses the denylisted routes", async () => {
  const gate = createGateServer();
  const server = createServer(async (req, res) => {
    const response = await gate(new Request(`http://127.0.0.1${req.url}`, { method: req.method }));
    res.writeHead(response.status, { "content-type": "application/json" });
    res.end(Buffer.from(await response.arrayBuffer()));
  });
  await new Promise((resolve) => server.listen(0, "127.0.0.1", resolve));
  const { port } = server.address();
  try {
    const denied = await fetch(`http://127.0.0.1:${port}/wallet`);
    assert.equal(denied.status, 403);
    const allowed = await fetch(`http://127.0.0.1:${port}/studio/tasks`);
    assert.equal(allowed.status, 200);
  } finally {
    await new Promise((resolve, reject) => server.close((error) => (error ? reject(error) : resolve())));
  }
});

/**
 * Worker tool events land on a monitor the API can read.
 */
import { createServer } from "node:http";
import { checkMessage } from "./protocol.mjs";

export function createMonitor() {
  const events = [];
  return {
    emit(event) {
      const row = {
        type: "worker.event",
        taskId: event.taskId,
        name: event.name,
        detail: event.detail ?? "",
      };
      const errors = checkMessage(row);
      if (errors.length) throw new Error(errors.join("; "));
      events.push(row);
      return row;
    },
    list() {
      return events.map((event) => ({ ...event }));
    },
  };
}

export function fakeWorker(monitor, taskId = "t1") {
  monitor.emit({ taskId, name: "tool.read", detail: "docs/v2/README.md" });
  monitor.emit({ taskId, name: "tool.write", detail: "studio note" });
  return monitor.list();
}

export function listenMonitor(monitor = createMonitor()) {
  const server = createServer((req, res) => {
    if (req.method === "GET" && req.url === "/events") {
      res.writeHead(200, { "content-type": "application/json" });
      res.end(JSON.stringify({ events: monitor.list() }));
      return;
    }
    res.writeHead(404);
    res.end();
  });
  return new Promise((resolve) => {
    server.listen(0, "127.0.0.1", () => {
      const { port } = server.address();
      resolve({ server, url: `http://127.0.0.1:${port}` });
    });
  });
}

